package com.huawei.oss.wireless.experienceassuranceservice.common.impl.utils;

import com.huawei.bsp.log.OssLog;
import com.huawei.bsp.log.OssLogFactory;
import com.huawei.bsp.remoteservice.exception.ServiceException;
import com.huawei.maos.commons.deploy.EnvUtil;
import com.huawei.maos.commons.text.StringUtil;
import com.huawei.oss.rest.util.RestCaller;
import com.huawei.oss.rest.util.RestMethod;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.stream.Collectors;

/**
 * 实例工具类
 *
 * @since 2025/09/09
 */
public class InstanceUtils {
    private static final OssLog LOGGER = OssLogFactory.getLogger(InstanceUtils.class);

    private static final String INSTANCE_ONLY_POLICY = "instanceOnly";

    private static final String BACKEND_LIST_POLICY_HEADER = "XX-Backend-List-Policy";

    private static final String BACKEND_LIST_HEADER = "Xx-Backend-List";

    private static final String ALL_INSTANCES_PREFIX = "all=";

    private static final String POD_NAME_ENV = "POD_NAME";

    private static final String INSTANCE_ID_SEPARATOR = ",";

    private static final String INSTANCE_NAME_SEPARATOR = "-";

    private static final String POLICY_URL = "/rest/oss/inner/experienceassurance/v1/policy";

    /**
     * 查询所有实例ID
     *
     * @return 所有实例ID列表
     */
    public static List<Integer> queryAllInstanceIds() {
        try {
            LOGGER.info("queryAllInstanceIds start");
            Map<String, String> headerMap = new java.util.HashMap<>();
            headerMap.put(BACKEND_LIST_POLICY_HEADER, INSTANCE_ONLY_POLICY);
            com.huawei.oss.rest.util.Response response = RestCaller.caller()
                .setMethod(RestMethod.POST)
                .setUriString(POLICY_URL)
                .setHeaderMap(headerMap)
                .call();
            Map<String, String> respHeaderMap = response.getHeaders();
            String backendList = getBackendList(respHeaderMap);
            if (StringUtil.isEmpty(backendList)) {
                LOGGER.warn("backendList is empty");
                return new ArrayList<>();
            }
            String[] instanceNames = backendList.split(INSTANCE_ID_SEPARATOR);
            List<Integer> instanceIds = new ArrayList<>();
            for (String instanceName : instanceNames) {
                if (StringUtil.isEmpty(instanceName)) {
                    continue;
                }
                Optional<Integer> instanceId = parseInstanceId(instanceName);
                if (instanceId.isPresent()) {
                    instanceIds.add(instanceId.get());
                }
            }
            LOGGER.info("queryAllInstanceIds result: {}", instanceIds);
            return instanceIds;
        } catch (ServiceException e) {
            LOGGER.error("queryAllInstanceIds ServiceException", e);
            return new ArrayList<>();
        } catch (Exception e) {
            LOGGER.error("queryAllInstanceIds unexpected exception", e);
            return new ArrayList<>();
        }
    }

    /**
     * 查询当前实例ID
     *
     * @return 当前实例ID
     */
    public static Optional<Integer> queryCurrentInstanceId() {
        try {
            LOGGER.info("queryCurrentInstanceId start");
            String podName = EnvUtil.getEnv(POD_NAME_ENV);
            if (StringUtil.isEmpty(podName)) {
                LOGGER.warn("POD_NAME env is empty");
                return Optional.empty();
            }
            Optional<Integer> instanceId = parseInstanceId(podName);
            LOGGER.info("queryCurrentInstanceId result: {}", instanceId);
            return instanceId;
        } catch (Exception e) {
            LOGGER.error("queryCurrentInstanceId error", e);
            return Optional.empty();
        }
    }

    /**
     * 从响应头中获取后端实例列表
     *
     * @param respHeaderMap 响应头
     * @return 后端实例列表字符串
     */
    private static String getBackendList(Map<String, String> respHeaderMap) {
        if (respHeaderMap == null) {
            LOGGER.warn("respHeaderMap is null");
            return null;
        }
        String backendList = respHeaderMap.get(BACKEND_LIST_HEADER);
        if (StringUtil.isEmpty(backendList)) {
            LOGGER.warn("BACKEND_LIST_HEADER not found in response headers");
            return null;
        }
        if (!backendList.startsWith(ALL_INSTANCES_PREFIX)) {
            LOGGER.warn("backendList {} does not start with {}", backendList, ALL_INSTANCES_PREFIX);
            return null;
        }
        return backendList.substring(ALL_INSTANCES_PREFIX.length());
    }

    /**
     * 解析实例名称获取实例ID
     *
     * @param instanceName 实例名称
     * @return 实例ID
     */
    private static Optional<Integer> parseInstanceId(String instanceName) {
        try {
            String[] parts = instanceName.split(INSTANCE_NAME_SEPARATOR);
            if (parts.length == 0) {
                LOGGER.warn("instanceName {} has no parts", instanceName);
                return Optional.empty();
            }
            String lastPart = parts[parts.length - 1];
            if (StringUtil.isEmpty(lastPart)) {
                LOGGER.warn("last part of instanceName {} is empty", instanceName);
                return Optional.empty();
            }
            int instanceId = Integer.parseInt(lastPart);
            LOGGER.info("parseInstanceId {} -> {}", instanceName, instanceId);
            return Optional.of(instanceId);
        } catch (NumberFormatException e) {
            LOGGER.warn("parseInstanceId {} failed, last part is not numeric", instanceName);
            return Optional.empty();
        }
    }
}
